-- Упражнения книги 19, глава 23 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-ensure-line', 0, 'func', 'Строка в файле: ensure_line', 'Напишите функцию ensure_line(text, line, regexp=None, state="present", insertafter=None) по образцу модуля lineinfile. Файл — строка из строк, каждая заканчивается на \n; один завершающий \n не создаёт лишней пустой строки. Верните кортеж (новый_текст, changed). state="present": если regexp задан, найдите строки, где re.search(regexp, строка) успешен; если такие есть, замените ПОСЛЕДНЮЮ из них на line (если она уже равна line, ничего не меняется). Если regexp не задан, а строка line уже есть в файле целиком, ничего не меняется. Если надо вставить строку (совпадений нет или regexp не задан): при insertafter равном None или "EOF" — в конец файла; иначе — сразу после ПОСЛЕДНЕЙ строки, где re.search(insertafter, строка) успешен, а если таких нет — в конец. insertafter при замене не используется. state="absent": если regexp задан, удалите ВСЕ строки с re.search(regexp, строка); иначе удалите все строки, равные line. Если содержимое не изменилось, верните исходный text без правок и False. Иначе новый текст — все строки, каждая с \n на конце, и True.', 'def ensure_line(text, line, regexp=None, state="present", insertafter=None):
    pass
', 'Разбейте text.split("\n"), уберите последний пустой элемент, работайте со списком; если список не изменился, верните исходный text.', '{"func": "ensure_line", "tests": [{"args": ["a\nb\n", "c"], "expected": {"__tuple__": ["a\nb\nc\n", true]}}, {"args": ["a\nb\nc\n", "b"], "expected": {"__tuple__": ["a\nb\nc\n", false]}}, {"args": ["# sshd_config\nPort 22\n#PermitRootLogin prohibit-password\nUsePAM yes\n", "PermitRootLogin no", "^#?PermitRootLogin"], "expected": {"__tuple__": ["# sshd_config\nPort 22\nPermitRootLogin no\nUsePAM yes\n", true]}}, {"args": ["PermitRootLogin yes\nX\nPermitRootLogin prohibit-password\n", "PermitRootLogin no", "^PermitRootLogin"], "expected": {"__tuple__": ["PermitRootLogin yes\nX\nPermitRootLogin no\n", true]}}, {"args": ["A=1\nB=2\n", "B=2", "^B="], "expected": {"__tuple__": ["A=1\nB=2\n", false]}}, {"args": ["[main]\nx=1\n[other]\ny=2\n", "z=9", null, "present", "^\\[main\\]"], "expected": {"__tuple__": ["[main]\nz=9\nx=1\n[other]\ny=2\n", true]}}, {"args": ["a\nb\n", "c", null, "present", "^zzz"], "expected": {"__tuple__": ["a\nb\nc\n", true]}}, {"args": ["k=1\n[m]\n", "k=2", "^k=", "present", "^\\[m\\]"], "expected": {"__tuple__": ["k=2\n[m]\n", true]}}, {"args": ["a\n#x\nb\n#y\n", "", "^#", "absent"], "expected": {"__tuple__": ["a\nb\n", true]}}, {"args": ["a\nab\na\n", "a", null, "absent"], "expected": {"__tuple__": ["ab\n", true]}}, {"args": ["a\n", "zz", null, "absent"], "expected": {"__tuple__": ["a\n", false]}}, {"args": ["", "x"], "expected": {"__tuple__": ["x\n", true]}}, {"args": ["a", "a"], "expected": {"__tuple__": ["a", false]}}, {"args": ["a\n", "a", null, "absent"], "expected": {"__tuple__": ["", true]}}, {"args": ["x=1\nx=2\n", "x=2", "^x="], "expected": {"__tuple__": ["x=1\nx=2\n", false]}}, {"args": ["[a]\n[b]\n[a]\n", "v=1", null, "present", "^\\[a\\]"], "expected": {"__tuple__": ["[a]\n[b]\n[a]\nv=1\n", true]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-plan', 1, 'func', 'План: желаемое против фактического', 'Напишите функцию plan(desired, actual): сравните желаемое состояние хоста с фактическим и верните словарь {"changed": bool, "actions": [...]}, где actions — список кортежей (операция, имя). desired: необязательные ключи "packages" (словарь имя → "present" или "absent"), "users" (так же), "files" (путь → {"content": строка, "mode": строка вида "0644"}) и "services" (имя → "running" или "stopped"). actual: "packages" — список установленных имён, "users" — список существующих, "files" — путь → {"content", "mode"} (файла может не быть), "services" — имя → "running"/"stopped" (службы, которой нет в словаре, считать остановленной). Отсутствующий ключ — пустая секция. Порядок действий: сначала все пакеты, затем пользователи, затем файлы, затем службы; внутри секции — по имени (по возрастанию). Правила: пакет present и не установлен → ("install", имя); absent и установлен → ("remove", имя). Пользователь так же: ("useradd", имя) и ("userdel", имя). Файл: нет файла или content отличается → ("write", путь); иначе, если отличается только mode → ("chmod", путь). Служба: желаем running, а не running → ("start", имя); желаем stopped, а running → ("stop", имя). Ничего не сверенное не трогаем (лишние файлы и пакеты остаются). changed равен True, если действия есть.', 'def plan(desired, actual):
    pass
', 'Четыре цикла по sorted(желаемое) в нужном порядке; actions собирайте в один список, changed = bool(actions).', '{"func": "plan", "tests": [{"args": [{"packages": {"nginx": "present", "telnet": "absent"}, "users": {"deploy": "present"}, "files": {"/etc/nginx/nginx.conf": {"content": "worker_processes auto;\nevents {}\n", "mode": "0644"}, "/etc/motd": {"content": "hi\n", "mode": "0644"}}, "services": {"nginx": "running", "cups": "stopped"}}, {"packages": ["telnet", "vim"], "users": ["root"], "files": {"/etc/motd": {"content": "hi\n", "mode": "0600"}}, "services": {"cups": "running"}}], "expected": {"changed": true, "actions": [{"__tuple__": ["install", "nginx"]}, {"__tuple__": ["remove", "telnet"]}, {"__tuple__": ["useradd", "deploy"]}, {"__tuple__": ["chmod", "/etc/motd"]}, {"__tuple__": ["write", "/etc/nginx/nginx.conf"]}, {"__tuple__": ["stop", "cups"]}, {"__tuple__": ["start", "nginx"]}]}}, {"args": [{"packages": {"nginx": "present", "telnet": "absent"}, "users": {"deploy": "present"}, "files": {"/etc/nginx/nginx.conf": {"content": "worker_processes auto;\nevents {}\n", "mode": "0644"}, "/etc/motd": {"content": "hi\n", "mode": "0644"}}, "services": {"nginx": "running", "cups": "stopped"}}, {"packages": ["nginx", "vim"], "users": ["root", "deploy"], "files": {"/etc/nginx/nginx.conf": {"content": "worker_processes auto;\nevents {}\n", "mode": "0644"}, "/etc/motd": {"content": "hi\n", "mode": "0644"}}, "services": {"nginx": "running", "cups": "stopped"}}], "expected": {"changed": false, "actions": []}}, {"args": [{}, {}], "expected": {"changed": false, "actions": []}}, {"args": [{"files": {"/etc/a": {"content": "x", "mode": "0600"}}}, {"files": {"/etc/a": {"content": "x", "mode": "0644"}}}], "expected": {"changed": true, "actions": [{"__tuple__": ["chmod", "/etc/a"]}]}}, {"args": [{"files": {"/etc/a": {"content": "y", "mode": "0644"}}}, {"files": {"/etc/a": {"content": "x", "mode": "0600"}}}], "expected": {"changed": true, "actions": [{"__tuple__": ["write", "/etc/a"]}]}}, {"args": [{"services": {"b": "running", "a": "running"}}, {"services": {"a": "running"}}], "expected": {"changed": true, "actions": [{"__tuple__": ["start", "b"]}]}}, {"args": [{"services": {"a": "stopped"}}, {"services": {}}], "expected": {"changed": false, "actions": []}}, {"args": [{"packages": {"z": "present", "a": "present"}, "users": {"u": "absent"}}, {"users": ["u", "v"]}], "expected": {"changed": true, "actions": [{"__tuple__": ["install", "a"]}, {"__tuple__": ["install", "z"]}, {"__tuple__": ["userdel", "u"]}]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-recap', 2, 'func', 'Разбор PLAY RECAP', 'Напишите функцию parse_recap(text): разберите итог ansible-playbook и верните кортеж (stats, bad). Итог начинается строкой, которая начинается с "PLAY RECAP"; если такой строки нет, верните ({}, []). Строки после неё читаются до первой пустой (из одних пробелов) строки. Строка хоста выглядит как имя, пробелы, двоеточие, пробелы и пары имя=число: "web1       : ok=2    changed=1    unreachable=0    failed=0 ..."; имя — без пробелов, строки другого вида пропустите. stats — словарь имя хоста → словарь ровно с семью ключами ok, changed, unreachable, failed, skipped, rescued, ignored (целые числа; счётчик, которого нет в строке, равен 0; лишние пары игнорируются). Если хост встретился дважды, побеждает последняя строка. bad — отсортированный список хостов, у которых failed > 0 или unreachable > 0. Всё, что до строки PLAY RECAP и после пустой строки, не учитывается.', 'def parse_recap(text):
    pass
', 're.match(r''^(\S+)\s+:\s+(.*)$'', line) даёт имя и остаток; re.findall(r''(\w+)=(\d+)'', остаток) — счётчики.', '{"func": "parse_recap", "tests": [{"args": ["PLAY [web] *********************************************************************\n\nTASK [Gathering Facts] *********************************************************\nok: [web1]\nok: [web2]\nfatal: [db1]: UNREACHABLE! => {\"changed\": false, \"msg\": \"Failed to connect to the host via ssh\", \"unreachable\": true}\n\nTASK [Install nginx.conf] ******************************************************\nchanged: [web1]\nok: [web2]\n\nPLAY RECAP *********************************************************************\ndb1                        : ok=0    changed=0    unreachable=1    failed=0    skipped=0    rescued=0    ignored=0   \nweb1                       : ok=2    changed=1    unreachable=0    failed=0    skipped=0    rescued=0    ignored=0   \nweb2                       : ok=2    changed=0    unreachable=0    failed=0    skipped=1    rescued=0    ignored=0   \n\nWednesday 04 November 2026  10:15:02 +0000 (0:00:00.500) 0:00:03.100 *****\n"], "expected": {"__tuple__": [{"db1": {"ok": 0, "changed": 0, "unreachable": 1, "failed": 0, "skipped": 0, "rescued": 0, "ignored": 0}, "web1": {"ok": 2, "changed": 1, "unreachable": 0, "failed": 0, "skipped": 0, "rescued": 0, "ignored": 0}, "web2": {"ok": 2, "changed": 0, "unreachable": 0, "failed": 0, "skipped": 1, "rescued": 0, "ignored": 0}}, ["db1"]]}}, {"args": ["PLAY RECAP *********************************************************************\n10.0.0.5                   : ok=3    changed=1    unreachable=0    failed=1    skipped=0    rescued=1    ignored=0   \nlocalhost                  : ok=1    changed=0    unreachable=0    failed=0    skipped=0    rescued=0    ignored=1   \nweb-01.example.org         : ok=4    changed=4    unreachable=0    failed=0    skipped=0    rescued=0    ignored=0   \n"], "expected": {"__tuple__": [{"10.0.0.5": {"ok": 3, "changed": 1, "unreachable": 0, "failed": 1, "skipped": 0, "rescued": 1, "ignored": 0}, "localhost": {"ok": 1, "changed": 0, "unreachable": 0, "failed": 0, "skipped": 0, "rescued": 0, "ignored": 1}, "web-01.example.org": {"ok": 4, "changed": 4, "unreachable": 0, "failed": 0, "skipped": 0, "rescued": 0, "ignored": 0}}, ["10.0.0.5"]]}}, {"args": ["PLAY RECAP ***\nweb1                       : ok=3    changed=2    unreachable=0    failed=0   \nweb2                       : ok=1    changed=0    unreachable=0    failed=2   \n"], "expected": {"__tuple__": [{"web1": {"ok": 3, "changed": 2, "unreachable": 0, "failed": 0, "skipped": 0, "rescued": 0, "ignored": 0}, "web2": {"ok": 1, "changed": 0, "unreachable": 0, "failed": 2, "skipped": 0, "rescued": 0, "ignored": 0}}, ["web2"]]}}, {"args": ["TASK [x] ***\nok: [web1]\n"], "expected": {"__tuple__": [{}, []]}}, {"args": [""], "expected": {"__tuple__": [{}, []]}}, {"args": ["PLAY RECAP ***\n\nweb1 : ok=1 changed=0 unreachable=0 failed=0\n"], "expected": {"__tuple__": [{}, []]}}, {"args": ["PLAY RECAP ***\nweb1 : ok=1 changed=0 unreachable=0 failed=0\nweb1 : ok=2 changed=1 unreachable=0 failed=1\nnot a host line\n"], "expected": {"__tuple__": [{"web1": {"ok": 2, "changed": 1, "unreachable": 0, "failed": 1, "skipped": 0, "rescued": 0, "ignored": 0}}, ["web1"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-handlers', 3, 'func', 'Какие обработчики сработают', 'Смоделируйте обработчики Ansible для одного хоста. Напишите функцию run_handlers(handlers, tasks, force=False): handlers — список имён обработчиков в порядке их определения (имена уникальны), tasks — список троек (имя, статус, notify), где статус — "ok", "changed", "skipped" или "failed", а notify — список имён обработчиков. Верните список имён обработчиков в порядке их выполнения. Правила: задачи идут по порядку. Задача со статусом "changed" ставит свои notify-имена в очередь (имена, которых нет в handlers, игнорируются; повторное уведомление ничего не добавляет). Задачи с другим статусом ничего в очередь не ставят. Задача с именем "meta: flush_handlers" (её статус "ok") немедленно выполняет очередь и очищает её. Выполнение очереди: каждый уведомлённый обработчик один раз, в порядке списка handlers, а не в порядке уведомлений. После последней задачи очередь выполняется так же. Если задача имеет статус "failed", обработка останавливается: оставшиеся задачи не рассматриваются; очередь выполняется, только если force равен True, иначе обработчики из очереди не выполняются. Уже выполненные ранее по flush остаются в результате.', 'def run_handlers(handlers, tasks, force=False):
    pass
', 'Храните очередь во множестве, а при выполнении проходите по списку handlers и берите те, что в множестве.', '{"func": "run_handlers", "tests": [{"args": [["reload sshd", "restart nginx", "restart chronyd"], []], "expected": []}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["conf", "changed", ["restart nginx"]], ["conf2", "changed", ["restart nginx"]]]], "expected": ["restart nginx"]}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["a", "changed", ["restart chronyd", "reload sshd"]]]], "expected": ["reload sshd", "restart chronyd"]}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["a", "ok", ["restart nginx"]], ["b", "skipped", ["restart nginx"]]]], "expected": []}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["a", "changed", ["restart nginx"]], ["meta: flush_handlers", "ok", []], ["b", "changed", ["restart nginx", "reload sshd"]]]], "expected": ["restart nginx", "reload sshd", "restart nginx"]}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["a", "changed", ["restart nginx"]], ["b", "failed", []], ["c", "changed", ["reload sshd"]]]], "expected": []}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["a", "changed", ["restart nginx"]], ["b", "failed", []], ["c", "changed", ["reload sshd"]]], true], "expected": ["restart nginx"]}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["a", "changed", ["no such handler"]]]], "expected": []}, {"args": [["reload sshd", "restart nginx", "restart chronyd"], [["a", "changed", ["reload sshd"]], ["meta: flush_handlers", "ok", []], ["b", "failed", []]], false], "expected": ["reload sshd"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-retry', 4, 'func', 'Повторы с нарастающей паузой', 'Напишите функцию retry_plan(outcomes, base, factor, cap, max_retries, max_elapsed) — расчёт повторов без реальных пауз. outcomes — список результатов попыток по номерам: попытка с номером k (с нуля) удаётся, если k < len(outcomes) и outcomes[k] равно True; попытки за пределами списка не удаются. Все числа целые. Ход: первая попытка идёт сразу. Удалась — верните (True, число_попыток, суммарная_пауза). Не удалась — смотрим, сколько повторов уже было (r = число_попыток − 1). Если r >= max_retries, сдаёмся. Иначе пауза перед повтором delay = min(cap, base * factor ** r) (r — число уже сделанных повторов). Если суммарная пауза + delay больше max_elapsed, сдаёмся, не спя; иначе «спим» (суммарная пауза += delay) и делаем следующую попытку. Сдались — верните (False, число_попыток, суммарная_пауза). Пауза берётся без случайности (jitter нет).', 'def retry_plan(outcomes, base, factor, cap, max_retries, max_elapsed):
    pass
', 'Цикл while True: попытка, проверка успеха, проверка r >= max_retries, расчёт delay и проверка лимита времени.', '{"func": "retry_plan", "tests": [{"args": [[true], 5, 2, 60, 3, 100], "expected": {"__tuple__": [true, 1, 0]}}, {"args": [[false, false, true], 5, 2, 60, 5, 100], "expected": {"__tuple__": [true, 3, 15]}}, {"args": [[], 1, 2, 60, 3, 100], "expected": {"__tuple__": [false, 4, 7]}}, {"args": [[false, false, false, false, false, false, false, false, false, false], 5, 2, 12, 6, 100], "expected": {"__tuple__": [false, 7, 63]}}, {"args": [[false, false, false, false, false, false, false, false, false, false], 5, 2, 60, 10, 30], "expected": {"__tuple__": [false, 3, 15]}}, {"args": [[false, false, false, true], 5, 2, 60, 3, 100], "expected": {"__tuple__": [true, 4, 35]}}, {"args": [[false, false, false, false, true], 5, 2, 60, 3, 100], "expected": {"__tuple__": [false, 4, 35]}}, {"args": [[false, true], 10, 3, 100, 4, 9], "expected": {"__tuple__": [false, 1, 0]}}, {"args": [[false, false, false, false, false, true], 2, 3, 20, 9, 50], "expected": {"__tuple__": [false, 5, 46]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-converge', 5, 'func', 'Сходится ли автоматика', 'Модель проверки идемпотентности. Состояние — список строк. Напишите функцию converge(lines, steps, max_runs) (max_runs >= 1). steps — список шагов [имя, операция, аргументы...]. Прогон — это все шаги по порядку на текущем списке. Операции: ["append", строка] — добавить строку в конец безусловно; ["ensure", строка] — добавить в конец, только если такой строки ещё нет; ["replace", старая, новая] — заменить каждую строку, равную старой, на новую; ["remove", строка] — удалить все строки, равные данной; ["stamp", префикс] — удалить все строки, начинающиеся с префикса, и добавить в конец префикс + номер прогона (номер с 1, как строка). Шаг «изменил», если список после него отличается от списка до него. После каждого прогона: если ни один шаг не изменил, остановиться и вернуть (номер_этого_прогона, []). Если дошли до max_runs и в последнем прогоне изменения были, вернуть (max_runs, имена_изменивших_шагов_последнего_прогона_в_порядке_шагов).', 'def converge(lines, steps, max_runs):
    pass
', 'Перед каждым шагом копируйте список (before), после шага сравнивайте; имена изменивших копите в списке на прогон.', '{"func": "converge", "tests": [{"args": [[], [["add-port", "ensure", "Port 22"], ["no-root", "ensure", "PermitRootLogin no"]], 5], "expected": {"__tuple__": [2, []]}}, {"args": [["Port 22"], [["add-port", "ensure", "Port 22"]], 5], "expected": {"__tuple__": [1, []]}}, {"args": [["a"], [["add-line", "append", "b"]], 3], "expected": {"__tuple__": [3, ["add-line"]]}}, {"args": [[], [["stamp", "stamp", "updated="], ["conf", "ensure", "x"]], 4], "expected": {"__tuple__": [4, ["stamp"]]}}, {"args": [["a"], [["to-b", "replace", "a", "b"], ["to-a", "replace", "b", "a"]], 3], "expected": {"__tuple__": [3, ["to-b", "to-a"]]}}, {"args": [["debug=1", "x"], [["drop", "remove", "debug=1"], ["x", "ensure", "x"]], 5], "expected": {"__tuple__": [2, []]}}, {"args": [["a"], [["to-b", "replace", "a", "b"], ["want-a", "ensure", "a"]], 3], "expected": {"__tuple__": [3, ["to-b", "want-a"]]}}, {"args": [["a"], [["add-line", "append", "b"], ["stamp", "stamp", "t="]], 1], "expected": {"__tuple__": [1, ["add-line", "stamp"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-apply-diff', 6, 'func', 'Применить унифицированный дифф', 'Режим проверки показывает изменения как унифицированный дифф. Напишите функцию apply_diff(old_text, diff_text), которая применяет такой дифф к тексту и возвращает новый текст, а при любом несоответствии — None. Текст — строки с \n на конце; один завершающий \n не создаёт пустой строки (так же для diff_text). Всё до первой строки-заголовка блока (--- и +++ в том числе) игнорируется. Заголовок блока: @@ -a,b +c,d @@, где ",b" и ",d" могут отсутствовать (тогда число равно 1). Тело блока — строки до следующего заголовка; каждая начинается с символа: пробел — контекст (строка должна совпадать с текущей строкой старого текста), "-" — удаляемая строка (должна совпадать), "+" — добавляемая; строки, начинающиеся с обратной косой черты ("\ No newline at end of file"), пропускаются; любая другая строка, в том числе пустая, — ошибка. Старая часть блока начинается со строки a (нумерация с 1); если b равно 0, это вставка после строки a (a = 0 — в самое начало). Число контекстных плюс удаляемых строк должно быть равно b, контекстных плюс добавляемых — равно d. Блоки идут по возрастанию и не перекрываются, иначе None. Строки между блоками и после них копируются без изменений. Если блоков нет, верните old_text как есть. Результат — все строки, каждая с \n на конце.', 'def apply_diff(old_text, diff_text):
    pass
', 'Регулярка ^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@; указатель ptr по старому тексту двигается на контекстных и удаляемых строках.', '{"func": "apply_diff", "tests": [{"args": ["line1\nline2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nline12\n", "--- before: f\n+++ after: f\n@@ -1,5 +1,5 @@\n line1\n-line2\n+LINE2\n line3\n line4\n line5\n@@ -9,4 +9,5 @@\n line9\n line10\n line11\n+extra\n line12\n"], "expected": "line1\nLINE2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nextra\nline12\n"}, {"args": ["line1\nline2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nline12\n", "--- before: f\n+++ after: f\n@@ -3,7 +3,6 @@\n line3\n line4\n line5\n-line6\n line7\n line8\n line9\n"], "expected": "line1\nline2\nline3\nline4\nline5\nline7\nline8\nline9\nline10\nline11\nline12\n"}, {"args": ["line1\nline2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nline12\n", "--- before: f\n+++ after: f\n@@ -1,3 +1,4 @@\n+first\n line1\n line2\n line3\n"], "expected": "first\nline1\nline2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nline12\n"}, {"args": ["line1\nline2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nline12\n", ""], "expected": "line1\nline2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nline12\n"}, {"args": ["a\nb\nc\n", "--- before: f\n+++ after: f\n@@ -1,3 +0,0 @@\n-a\n-b\n-c\n"], "expected": ""}, {"args": ["", "--- before: f\n+++ after: f\n@@ -0,0 +1,2 @@\n+x\n+y\n"], "expected": "x\ny\n"}, {"args": ["line1\nline2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nline12\nextra\n", "--- before: f\n+++ after: f\n@@ -1,5 +1,5 @@\n line1\n-line2\n+LINE2\n line3\n line4\n line5\n@@ -9,4 +9,5 @@\n line9\n line10\n line11\n+extra\n line12\n"], "expected": "line1\nLINE2\nline3\nline4\nline5\nline6\nline7\nline8\nline9\nline10\nline11\nextra\nline12\nextra\n"}, {"args": ["a\nb\nc\n", "--- a\n+++ b\n@@ -1,2 +1,2 @@\n a\n-b\n+B\n@@ -3 +3 @@\n-c\n+C\n"], "expected": "a\nB\nC\n"}, {"args": ["a\nb\nc\n", "@@ -1,2 +1,2 @@\n a\n-X\n+B\n"], "expected": null}, {"args": ["a\nb\nc\n", "@@ -1,2 +1,3 @@\n a\n-b\n+B\n"], "expected": null}, {"args": ["a\nb\nc\n", "@@ -3 +3 @@\n-c\n+C\n@@ -1 +1 @@\n-a\n+A\n"], "expected": null}, {"args": ["a\nb\nc\n", "@@ -1 +1 @@\n-a\n\n+A\n"], "expected": null}, {"args": ["a\nb\nc\n", "@@ -1 +1 @@\n-a\n+A\n\\ No newline at end of file\n"], "expected": "A\nb\nc\n"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-host-vars', 7, 'func', 'Переменные хоста из инвентаря', 'Напишите функцию host_vars(inv, host): верните итоговые переменные хоста по правилам приоритета Ansible. inv повторяет YAML-инвентарь как словарь: верхний уровень — {"all": группа}, группа — словарь с необязательными ключами "vars" (словарь), "hosts" (имя хоста → словарь переменных хоста или None) и "children" (имя группы → группа). Имена групп не повторяются. Глубина группы: all имеет 0, её дети 1, их дети 2 и так далее. Хост входит в группу, если он перечислен в её hosts или входит в любую из её дочерних групп (на любую глубину). Сначала сливаются vars всех групп, куда входит хост, в порядке возрастания (глубина, имя группы); более поздняя перекрывает более раннюю. Затем поверх всего накладываются переменные самого хоста из каждой записи hosts, где он перечислен, в том же порядке групп (None и пустой словарь ничего не добавляют). Если хоста нет в инвентаре, верните пустой словарь.', 'def host_vars(inv, host):
    pass
', 'Обойдите дерево рекурсивно, собирая (глубина, имя, группа); отсортируйте; функция contains(группа) проверяет hosts и детей.', '{"func": "host_vars", "tests": [{"args": [{"all": {"vars": {"ntp": "pool.example.org", "env": "prod"}, "children": {"web": {"vars": {"ntp": "10.0.0.1", "port": 80}, "hosts": {"web1": {}, "web2": {"ntp": "10.0.0.9"}}}, "db": {"vars": {"port": 5432}, "hosts": {"db1": null}}}}}, "web1"], "expected": {"ntp": "10.0.0.1", "env": "prod", "port": 80}}, {"args": [{"all": {"vars": {"ntp": "pool.example.org", "env": "prod"}, "children": {"web": {"vars": {"ntp": "10.0.0.1", "port": 80}, "hosts": {"web1": {}, "web2": {"ntp": "10.0.0.9"}}}, "db": {"vars": {"port": 5432}, "hosts": {"db1": null}}}}}, "web2"], "expected": {"ntp": "10.0.0.9", "env": "prod", "port": 80}}, {"args": [{"all": {"vars": {"ntp": "pool.example.org", "env": "prod"}, "children": {"web": {"vars": {"ntp": "10.0.0.1", "port": 80}, "hosts": {"web1": {}, "web2": {"ntp": "10.0.0.9"}}}, "db": {"vars": {"port": 5432}, "hosts": {"db1": null}}}}}, "db1"], "expected": {"ntp": "pool.example.org", "env": "prod", "port": 5432}}, {"args": [{"all": {"vars": {"ntp": "pool.example.org", "env": "prod"}, "children": {"web": {"vars": {"ntp": "10.0.0.1", "port": 80}, "hosts": {"web1": {}, "web2": {"ntp": "10.0.0.9"}}}, "db": {"vars": {"port": 5432}, "hosts": {"db1": null}}}}}, "nope"], "expected": {}}, {"args": [{"all": {"vars": {"a": "all"}, "children": {"zeta": {"vars": {"a": "zeta", "z": 1}, "children": {"leaf": {"vars": {"a": "leaf"}, "hosts": {"h1": {}}}}}, "alpha": {"vars": {"a": "alpha", "b": "alpha"}, "hosts": {"h1": null, "h2": {"b": "own"}}}, "beta": {"vars": {"b": "beta"}, "hosts": {"h1": {"c": 3}}}}}}, "h1"], "expected": {"a": "leaf", "b": "beta", "z": 1, "c": 3}}, {"args": [{"all": {"vars": {"a": "all"}, "children": {"zeta": {"vars": {"a": "zeta", "z": 1}, "children": {"leaf": {"vars": {"a": "leaf"}, "hosts": {"h1": {}}}}}, "alpha": {"vars": {"a": "alpha", "b": "alpha"}, "hosts": {"h1": null, "h2": {"b": "own"}}}, "beta": {"vars": {"b": "beta"}, "hosts": {"h1": {"c": 3}}}}}}, "h2"], "expected": {"a": "alpha", "b": "own"}}, {"args": [{"all": {"children": {"x": {"children": {"y": {"vars": {"k": "y"}, "hosts": {"h": {"m": 1}}}}, "vars": {"k": "x", "j": "x"}}, "w": {"hosts": {"h": {"m": 2}}, "vars": {"k": "w", "j": "w"}}}}}, "h"], "expected": {"k": "y", "j": "x", "m": 1}}, {"args": [{"all": {}}, "h"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 23, 'la23-exit-status', 8, 'func', 'Код возврата для cron и systemd', 'Обёртка запускает плейбук и должна завершиться кодом, понятным cron и таймеру systemd. Напишите функцию exit_status(stats, audit): stats — словарь хост → словарь счётчиков (ключи ok, changed, unreachable, failed; отсутствующий считается 0), audit — bool (режим проверки без применения). Таблица, по порядку проверки (берётся первое подходящее): если у какого-либо хоста failed > 0 — 1; иначе если у какого-либо unreachable > 0 — 3; иначе если у какого-либо changed > 0 — 4 при audit=True (найден дрейф) и 2 при audit=False (изменения применены); иначе — 0. Пустой stats даёт 0.', 'def exit_status(stats, audit):
    pass
', 'Три any(...) по stats.values() и цепочка if в нужном порядке.', '{"func": "exit_status", "tests": [{"args": [{}, false], "expected": 0}, {"args": [{"web1": {"ok": 5, "changed": 0, "unreachable": 0, "failed": 0}, "web2": {"ok": 5, "changed": 0, "unreachable": 0, "failed": 0}}, false], "expected": 0}, {"args": [{"web1": {"ok": 5, "changed": 2, "unreachable": 0, "failed": 0}, "web2": {"ok": 5, "changed": 0, "unreachable": 0, "failed": 0}}, false], "expected": 2}, {"args": [{"web1": {"ok": 5, "changed": 2, "unreachable": 0, "failed": 0}, "web2": {"ok": 5, "changed": 0, "unreachable": 0, "failed": 0}}, true], "expected": 4}, {"args": [{"web1": {"ok": 5, "changed": 2, "unreachable": 0, "failed": 0}, "db1": {"ok": 0, "changed": 0, "unreachable": 1, "failed": 0}}, false], "expected": 3}, {"args": [{"web1": {"ok": 5, "changed": 2, "unreachable": 0, "failed": 1}, "db1": {"ok": 0, "changed": 0, "unreachable": 1, "failed": 0}}, true], "expected": 1}, {"args": [{"web1": {"ok": 3}}, true], "expected": 0}, {"args": [{"a": {"ok": 1, "changed": 0, "unreachable": 0, "failed": 0}, "b": {"ok": 1, "changed": 0, "unreachable": 1, "failed": 0}}, true], "expected": 3}, {"args": [{"a": {"ok": 1, "changed": 1, "unreachable": 0, "failed": 0}, "b": {"ok": 0, "changed": 0, "unreachable": 0, "failed": 2}}, false], "expected": 1}]}');
